', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/checkbox-group--framework-react--style-modern/google/gemini-3-flash-preview__s2/app.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents='const { useState } = React;

const questions = [
  {
    id: 1,
    question: "Which of the following are statically typed languages?",
    helpText: "Statically typed languages perform type checking at compile-time.",
    options: ["Java", "Python", "C++", "Ruby"],
    answers: ["Java", "C++"]
  },
  {
    id: 2,
    question: "Which of these languages are commonly used for systems programming?",
    options: ["Rust", "PHP", "C", "JavaScript"],
    answers: ["Rust", "C"]
  },
  {
    id: 3,
    question: "Which of these languages were released before 1990?",
    options: ["C", "Python", "Fortran", "Java"],
    answers: ["C", "Fortran"]
  }
];

function Quiz() {
  const [selectedOptions, setSelectedOptions] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);

  const handleCheckboxChange = (questionId, option) => {
    const currentSelected = selectedOptions[questionId] || [];
    let newSelected;
    if (currentSelected.includes(option)) {
      newSelected = currentSelected.filter(item => item !== option);
    } else {
      newSelected = [...currentSelected, option];
    }
    setSelectedOptions({
      ...selectedOptions,
      [questionId]: newSelected
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let calculatedScore = 0;
    questions.forEach(q => {
      const userAnswers = selectedOptions[q.id] || [];
      const isCorrect = 
        userAnswers.length === q.answers.length && 
        userAnswers.every(val => q.answers.includes(val));
      if (isCorrect) calculatedScore++;
    });
    setScore(calculatedScore);
    setSubmitted(true);
  };

  return (
    <main className="quiz-container">
      <h1>Computer Languages Quiz</h1>
      <form onSubmit={handleSubmit}>
        {questions.map((q) => (
          <div key={q.id} className="form-field">
            <fieldset>
              <legend>{q.question}</legend>
              {q.helpText && <p id={`help-${q.id}`} className="help-text">{q.helpText}</p>}
              <div className="options-group">
                {q.options.map((option) => (
                  <label key={option} className="option-label">
                    <input
                      type="checkbox"
                      checked={(selectedOptions[q.id] || []).includes(option)}
                      onChange={() => handleCheckboxChange(q.id, option)}
                      disabled={submitted}
                      aria-describedby={q.helpText ? `help-${q.id}` : undefined}
                    />
                    {option}
                  </label>
                ))}
              </div>
            </fieldset>
          </div>
        ))}
        {!submitted && (
          <button type="submit" className="submit-btn">Submit Quiz</button>
        )}
      </form>
      {submitted && (
        <div className="results" aria-live="polite">
          <h3>Your Score: {score} / {questions.length}</h3>
          <button 
            onClick={() => { setSubmitted(false); setSelectedOptions({}); }}
            className="submit-btn reset-btn"
          >
            Try Again
          </button>
        </div>
      )}
    </main>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
